using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using System.Threading.Tasks;using ScreenRecorderLib;
namespace PCRecord {
 // Отдельное компактное окно: масштабируется по DPI и не исчезает вместе с основным.
 internal sealed class RecordingToolbar:Form {
  readonly CaptureEngine engine;readonly MenuButton pause=new MenuButton("Пауза","pause",false);readonly MenuButton stop=new MenuButton("Стоп","stop",true);readonly MenuButton open=new MenuButton("","open",false);readonly ToolTip tips=new ToolTip();
  float scale=1;bool stopping,dragging;Point origin;string time="00:00:00",state="Recording";
  public bool ExcludedFromCapture{get;private set;}
  public RecordingToolbar(CaptureEngine capture,Action restore){engine=capture;Text="PC Record — управление записью";TopMost=true;ShowInTaskbar=false;FormBorderStyle=FormBorderStyle.None;ControlBox=false;AutoScaleMode=AutoScaleMode.None;BackColor=Color.FromArgb(22,27,35);ForeColor=Color.White;StartPosition=FormStartPosition.Manual;DoubleBuffered=true;
   Controls.Add(pause);Controls.Add(stop);Controls.Add(open);pause.TabIndex=0;stop.TabIndex=1;open.TabIndex=2;open.AccessibleName="Открыть основное окно PC Record";pause.Click+=(s,e)=>TogglePause();stop.Click+=async(s,e)=>await StopRecording();open.Click+=(s,e)=>restore();tips.SetToolTip(open,"Открыть основное окно");tips.SetToolTip(stop,"Остановить и сохранить запись");tips.SetToolTip(this,"Перетащите панель за таймер");
   using(var g=CreateGraphics())scale=g.DpiX/96f;ClientSize=new Size((int)(550*scale),(int)(82*scale));LayoutButtons();
   Shown+=(s,e)=>{var area=Screen.FromControl(this).WorkingArea;Location=new Point(area.Left+(area.Width-Width)/2,area.Top+(int)(18*scale));ExcludedFromCapture=Recorder.SetExcludeFromCapture(Handle,true);};
   MouseDown+=(s,e)=>{if(e.Button==MouseButtons.Left&&e.X<210*scale){dragging=true;origin=e.Location;Capture=true;}};MouseMove+=(s,e)=>{if(dragging)Location=new Point(Location.X+e.X-origin.X,Location.Y+e.Y-origin.Y);};MouseUp+=(s,e)=>{dragging=false;Capture=false;};
  }
  void LayoutButtons(){pause.SetBounds((int)(224*scale),(int)(18*scale),(int)(112*scale),(int)(46*scale));stop.SetBounds((int)(346*scale),(int)(18*scale),(int)(116*scale),(int)(46*scale));open.SetBounds((int)(478*scale),(int)(18*scale),(int)(50*scale),(int)(46*scale));foreach(var b in new[]{pause,stop,open})b.ScaleFactor=scale;using(var path=Round(new RectangleF(0,0,Width,Height),18*scale)){var old=Region;Region=new Region(path);if(old!=null)old.Dispose();}}
  internal static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  protected override CreateParams CreateParams{get{var c=base.CreateParams;c.ClassStyle|=0x20000;return c;}}
  protected override bool ShowWithoutActivation{get{return true;}}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.ScaleTransform(scale,scale);using(var edge=new Pen(Color.FromArgb(68,79,96)))using(var line=new Pen(Color.FromArgb(47,56,70)))using(var label=new Font("Segoe UI",9,FontStyle.Bold,GraphicsUnit.Pixel))using(var digits=new Font("Consolas",25,FontStyle.Bold,GraphicsUnit.Pixel))using(var sub=new Font("Segoe UI",9,FontStyle.Regular,GraphicsUnit.Pixel)){using(var path=Round(new RectangleF(.5f,.5f,549,81),18))e.Graphics.DrawPath(edge,path);e.Graphics.DrawLine(line,207,18,207,64);e.Graphics.DrawString("PC RECORD",label,Brushes.LightSlateGray,24,12);using(var dot=new SolidBrush(state=="Paused"?Color.FromArgb(238,194,112):Color.FromArgb(250,118,131)))e.Graphics.FillEllipse(dot,24,39,8,8);e.Graphics.DrawString(time,digits,Brushes.White,42,27);e.Graphics.DrawString(state=="Paused"?"ПАУЗА":"ЗАПИСЬ",sub,Brushes.LightSlateGray,44,58);}}
  public void RefreshStatus(){var status=engine.Status();state=Data.Text(status,"state");time=state=="Countdown"?"СТАРТ "+Data.Num(status,"countdown"):TimeSpan.FromSeconds(Data.Num(status,"elapsed")).ToString(@"hh\:mm\:ss");pause.Text=state=="Paused"?"Далее":"Пауза";pause.Glyph=state=="Paused"?"play":"pause";pause.Enabled=!stopping&&(state=="Recording"||state=="Paused");stop.Enabled=!stopping&&(state=="Countdown"||state=="Recording"||state=="Paused");Invalidate();}
  public void TogglePause(){try{if(Data.Text(engine.Status(),"state")=="Paused")engine.Resume();else engine.Pause();RefreshStatus();}catch(Exception ex){MessageBox.Show(this,ex.Message,"PC Record");}}
  public async Task StopRecording(){if(stopping)return;stopping=true;RefreshStatus();try{await engine.Stop();Hide();}catch(Exception ex){MessageBox.Show(this,ex.Message,"PC Record");}finally{stopping=false;}}
  protected override void Dispose(bool disposing){if(disposing)tips.Dispose();base.Dispose(disposing);}
 }
 internal sealed class MenuButton:Button {
  public float ScaleFactor=1;public string Glyph;readonly bool danger;bool hover;
  public MenuButton(string text,string glyph,bool red){Text=text;Glyph=glyph;danger=red;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);MouseEnter+=(s,e)=>{hover=true;Invalidate();};MouseLeave+=(s,e)=>{hover=false;Invalidate();};}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Parent==null?Color.FromArgb(22,27,35):Parent.BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(ScaleFactor,ScaleFactor);float w=Width/ScaleFactor,h=Height/ScaleFactor;Color bg=danger?(hover?Color.FromArgb(255,146,155):Color.FromArgb(244,120,133)):(hover?Color.FromArgb(48,59,76):Color.FromArgb(32,40,52));Color fg=danger?Color.FromArgb(40,17,23):Color.FromArgb(233,239,247);if(!Enabled){bg=Color.FromArgb(37,44,55);fg=Color.FromArgb(112,124,140);}using(var path=RecordingToolbar.Round(new RectangleF(1,1,w-2,h-2),11))using(var fill=new SolidBrush(bg))using(var edge=new Pen(Focused?Color.FromArgb(146,181,255):Color.FromArgb(61,73,92),Focused?2:1)){g.FillPath(fill,path);if(!danger||Focused)g.DrawPath(edge,path);}float x=Text.Length==0?(w-16)/2:17,y=(h-16)/2;using(var pen=new Pen(fg,1.8f))using(var ink=new SolidBrush(fg))using(var font=new Font("Segoe UI",12,FontStyle.Bold,GraphicsUnit.Pixel)){if(Glyph=="pause"){g.FillRectangle(ink,x+2,y+2,4,12);g.FillRectangle(ink,x+10,y+2,4,12);}else if(Glyph=="stop"){g.FillRectangle(ink,x+2,y+2,12,12);}else if(Glyph=="play"){g.FillPolygon(ink,new[]{new PointF(x+3,y+1),new PointF(x+3,y+15),new PointF(x+15,y+8)});}else{g.DrawRectangle(pen,x,y+3,13,12);g.DrawLine(pen,x+6,y,x+16,y);g.DrawLine(pen,x+16,y,x+16,y+9);}if(Text.Length>0)g.DrawString(Text,font,ink,x+26,(h-16)/2);}}
 }
}